module MaxCliqueFinder(\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] N,\n    input [3:0] K,\n    input [63:0] adj_packed,\n    output reg [3:0] max_size,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE          = 3'd0;\n    localparam [2:0] INIT          = 3'd1;\n    localparam [2:0] CHECK_UPDATE  = 3'd2;\n    localparam [2:0] INCREMENT     = 3'd3;\n    localparam [2:0] DONE_STATE    = 3'd4;\n    \n    reg [2:0] state, next_state;\n    \n    // Computation registers\n    reg [7:0] subset_mask;\n    reg [7:0] max_mask;\n    reg early_terminate;\n    \n    // Combinational signals\n    reg is_clique_flag;\n    reg [3:0] current_size;\n    \n    // Popcount calculation\n    always @(*) begin\n        current_size = 4'd0;\n        for (integer i = 0; i < 8; i = i + 1) begin\n            if (i < N && subset_mask[i]) begin\n                current_size = current_size + 4'd1;\n            end\n        end\n    end\n\n    // Clique check logic\n    always @(*) begin\n        is_clique_flag = 1'b1;\n        for (integer i = 0; i < 8; i = i + 1) begin\n            if (i < N && subset_mask[i]) begin\n                for (integer j = i+1; j < 8; j = j + 1) begin\n                    if (j < N && subset_mask[j]) begin\n                        if (!adj_packed[i*8 + j]) begin\n                            is_clique_flag = 1'b0;\n                        end\n                    end\n                end\n            end\n        end\n    end\n\n    // FSM sequential logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            subset_mask <= 8'd0;\n            max_mask <= 8'd0;\n            max_size <= 4'd0;\n            done <= 1'b0;\n            early_terminate <= 1'b0;\n        end else begin\n            state <= next_state;\n\n            case (state)\n                INIT: begin\n                    subset_mask <= 8'd1;\n                    max_mask <= (8'd1 << N) - 8'd1;\n                    max_size <= 4'd0;\n                    early_terminate <= 1'b0;\n                end\n                \n                CHECK_UPDATE: begin\n                    if (is_clique_flag) begin\n                        if (current_size > max_size) begin\n                            max_size <= current_size;\n                        end\n                        if (current_size == K) begin\n                            early_terminate <= 1'b1;\n                        end\n                    end\n                end\n                \n                INCREMENT: begin\n                    subset_mask <= subset_mask + 8'd1;\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                end\n                \n                IDLE: begin\n                    done <= 1'b0;\n                end\n                default: ;\n            endcase\n        end\n    end\n\n    // FSM next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: begin\n                if (start) next_state = INIT;\n                else next_state = IDLE;\n            end\n            \n            INIT: begin\n                next_state = CHECK_UPDATE;\n            end\n            \n            CHECK_UPDATE: begin\n                next_state = INCREMENT;\n            end\n            \n            INCREMENT: begin\n                if (((subset_mask + 8'd1) > max_mask) || early_terminate) begin\n                    next_state = DONE_STATE;\n                end else begin\n                    next_state = CHECK_UPDATE;\n                end\n            end\n            \n            DONE_STATE: begin\n                next_state = IDLE;\n            end\n            \n            default: begin\n                next_state = IDLE;\n            end\n        endcase\n    end\n\nendmodule